import * as paymentService from "./paymentService";
import * as inventory from "./inventory";
import { checkout } from "./checkout";

afterEach(() => {
  vi.restoreAllMocks();
});

test("checkout calls paymentService.process with the cart total", async () => {
  const spy = vi.spyOn(paymentService, "process").mockResolvedValue({ ok: true });
  const cart = { items: [{ sku: "A", price: 40, qty: 2 }] };
  await checkout(cart, { type: "card", token: "tok_1" });
  expect(spy).toHaveBeenCalledTimes(1);
  expect(spy).toHaveBeenCalledWith(80);
});

test("checkout declines without charging when inventory cannot be reserved", async () => {
  vi.spyOn(inventory, "reserve").mockResolvedValue({ ok: false });
  const paySpy = vi.spyOn(paymentService, "process").mockResolvedValue({ ok: true });
  const cart = { items: [{ sku: "A", price: 40, qty: 2 }] };

  const result = await checkout(cart, { type: "card", token: "tok_1" });

  expect(result.status).toBe("declined");
  expect(result.orderId).toBeUndefined();
  expect(paySpy).not.toHaveBeenCalled();
});

test("checkout declines when the payment is rejected", async () => {
  vi.spyOn(inventory, "reserve").mockResolvedValue({ ok: true });
  vi.spyOn(paymentService, "process").mockResolvedValue({ ok: false });
  const cart = { items: [{ sku: "A", price: 40, qty: 2 }] };

  const result = await checkout(cart, { type: "card", token: "tok_1" });

  expect(result.status).toBe("declined");
  expect(result.orderId).toBeUndefined();
});

test("checkout declines an empty cart without touching payment or inventory", async () => {
  const paySpy = vi.spyOn(paymentService, "process").mockResolvedValue({ ok: true });
  const reserveSpy = vi.spyOn(inventory, "reserve").mockResolvedValue({ ok: true });

  const result = await checkout({ items: [] }, { type: "card", token: "tok_1" });

  expect(result.status).toBe("declined");
  expect(paySpy).not.toHaveBeenCalled();
  expect(reserveSpy).not.toHaveBeenCalled();
