import { CouponError } from './errors';
import { discountOf, isExpired, meetsMinSubtotal, round2, subtotalOf } from './pricing';

export type CartItem = { sku: string; price: number; qty: number };
export type Cart = { items: CartItem[] };

/** 某一时刻对某张券的计价结果，本身是个值，不会随购物车后续变动而失真。 */
export type Quote = {
  code: string;
  subtotal: number;
  discount: number;
  total: number;
};

export { CouponError } from './errors';
export type { CouponErrorReason } from './errors';
export type { Coupon } from './couponRepo';

export function createCart(): Cart {
  return { items: [] };
}

export function add(cart: Cart, sku: string, price: number, qty = 1): Cart {
  return { items: [...cart.items, { sku, price, qty }] };
}

export function total(cart: Cart): number {
  return subtotalOf(cart.items);
}

/**
 * 校验并计算优惠码。券不存在、已过期、或未达使用门槛都会抛 CouponError。
 * now 可注入，便于测试过期边界；默认取当前时间。
 */
export function applyCoupon(cart: Cart, code: string, now: Date = new Date()): Quote {
  const normalized = normalizeCode(code);
  const coupon = findCoupon(normalized);

  if (!coupon) {
    throw new CouponError('not_found', normalized, `优惠码 ${normalized} 不存在`);
  }
  if (isExpired(coupon, now)) {
    throw new CouponError('expired', normalized, `优惠码 ${normalized} 已于 ${coupon.expiresAt} 过期`);
  }

  const subtotal = subtotalOf(cart.items);
  if (!meetsMinSubtotal(coupon, subtotal)) {
    throw new CouponError(
      'min_subtotal_not_met',
      normalized,
      `优惠码 ${normalized} 需满 ${coupon.minSubtotal}，当前 ${subtotal}`,
    );
  }

  const discount = discountOf(coupon, subtotal);
  return { code: normalized, subtotal, discount, total: round2(subtotal - discount) };
}
