import { discountFor, subtotal, type LineItem } from './pricing';

export type Cart = { items: LineItem[]; coupon?: string };

export function createCart(): Cart {
  return { items: [] };
}

export function add(cart: Cart, sku: string, price: number, qty = 1): Cart {
  return { ...cart, items: [...cart.items, { sku, price, qty }] };
}

/** 校验券(存在、未过期)并挂到购物车上;门槛由 total 在结算时判断 */
export function applyCoupon(cart: Cart, code: string, now: Date = new Date()): Cart {
  const coupon = findCoupon(code);
  if (!coupon) throw new Error(`unknown coupon: ${code}`);
  if (now > coupon.expiresAt) throw new Error(`coupon expired: ${code}`);
  return { ...cart, coupon: coupon.code };
}

export function total(cart: Cart): number {
  const sub = subtotal(cart.items);
  const coupon = cart.coupon ? findCoupon(cart.coupon) : undefined;
  return coupon ? sub - discountFor(sub, coupon) : sub;
}
